import store from '../../redux/store';
import { printText } from "./primitives";
import lcdGetVoltage from "../lcdGetData/lcdGetVoltage";
import * as vl from '../validateValues';

export default function lcdShowVoltageOrPercentage(ctx: CanvasRenderingContext2D, prevValue: string | undefined, 
    color: string, colorAir: string, bgColor: string, localTemp: number
): string {
    const v = lcdGetVoltage(localTemp);

    if(v.val !== prevValue) {
        const model = store.getState().config.display.model[0];
        const dispModel = (model === 0 || model === 1) ? 0 : 1;
        const x = dispModel ? 198 : 220;
        const font = dispModel ? 14 : 11;
        const match = v.val.match(/[\d.]+/);
        const val = match ? parseFloat(match[0]) : -1;
        const dataValid = (
            vl.validateAnalogVoltage(val) || 
            vl.validateHighVoltage(val) || 
            vl.validatePercentage(val) ||
            vl.validateCO2(val)
        )
        printText(ctx, x, 7, 58, 16, dataValid ? v.val : '--', font, 'center', v.type ? colorAir : color, bgColor);
    }

    return v.val;
}